func (this *Bitso) ParseLedgerEntryType(typeVar any) any {
	var types map[string]any = map[string]any{
		"funding":    "transaction",
		"withdrawal": "transaction",
		"trade":      "trade",
		"fee":        "fee",
	}
	return this.SafeString(types, typeVar, typeVar)
}
func (this *Bitso) ParseLedgerEntry(item any, optionalArgs ...any) any {
	//
	//     {
	//         "eid": "2510b3e2bc1c87f584500a18084f35ed",
	//         "created_at": "2022-06-08T12:21:42+0000",
	//         "balance_updates": [{
	//             "amount": "0.00080000",
	//             "currency": "btc"
	//         }],
	//         "operation": "funding",
	//         "details": {
	//             "network": "btc",
	//             "method": "btc",
	//             "method_name": "Bitcoin",
	//             "asset": "btc",
	//             "protocol": "btc",
	//             "integration": "bitgo-v2",
	//             "fid": "6112c6369100d6ecceb7f54f17cf0511"
	//         }
	//     }
	//
	//  trade
	//     {
	//         "eid": "8976c6053f078f704f037d82a813678a",
	//         "created_at": "2022-06-08T17:01:48+0000",
	//         "balance_updates": [{
	//                 "amount": "59.21320500",
	//                 "currency": "mxn"
	//             },
	//             {
	//                 "amount": "-0.00010000",
	//                 "currency": "btc"
	//             }
	//         ],
	//         "operation": "trade",
	//         "details": {
	//             "tid": "72145428",
	//             "oid": "JO5TZmMZjzjlZDyT"
	//         }
	//     }
	//
	//  fee
	//     {
	//         "eid": "cbbb3c8d4e41723d25d2850dcb7c3c74",
	//         "created_at": "2022-06-08T17:01:48+0000",
	//         "balance_updates": [{
	//             "amount": "-0.38488583",
	//             "currency": "mxn"
	//         }],
	//         "operation": "fee",
	//         "details": {
	//             "tid": "72145428",
	//             "oid": "JO5TZmMZjzjlZDyT"
	//         }
	//     }
	currency := GetArg(optionalArgs, 0, nil)
	_ = currency
	var operation any = this.SafeString(item, "operation")
	var typeVar any = this.ParseLedgerEntryType(operation)
	var balanceUpdates any = this.SafeValue(item, "balance_updates", []any{})
	var firstBalance any = this.SafeValue(balanceUpdates, 0, map[string]any{})
	var direction any = nil
	var fee any = nil
	var amount any = this.SafeString(firstBalance, "amount")
	var currencyId any = this.SafeString(firstBalance, "currency")
	var code any = this.SafeCurrencyCode(currencyId, currency)
	currency = this.SafeCurrency(currencyId, currency)
	var details any = this.SafeValue(item, "details", map[string]any{})
	var referenceId any = this.SafeString2(details, "fid", "wid")
	if IsTrue(IsEqual(referenceId, nil)) {
		referenceId = this.SafeString(details, "tid")
	}
	if IsTrue(IsEqual(operation, "funding")) {
		direction = "in"
	} else if IsTrue(IsEqual(operation, "withdrawal")) {
		direction = "out"
	} else if IsTrue(IsEqual(operation, "trade")) {
		direction = nil
	} else if IsTrue(IsEqual(operation, "fee")) {
		direction = "out"
		var cost any = Precise.StringAbs(amount)
		fee = map[string]any{
			"cost":     cost,
			"currency": currency,
		}
	}
	var timestamp any = this.Parse8601(this.SafeString(item, "created_at"))
	return this.SafeLedgerEntry(map[string]any{
		"info":             item,
		"id":               this.SafeString(item, "eid"),
		"direction":        direction,
		"account":          nil,
		"referenceId":      referenceId,
		"referenceAccount": nil,
		"type":             typeVar,
		"currency":         code,
		"amount":           amount,
		"timestamp":        timestamp,
		"datetime":         this.Iso8601(timestamp),
		"before":           nil,
		"after":            nil,
		"status":           "ok",
		"fee":              fee,
	}, currency)
}

