func (this *Bitso) ParseTrade(trade any, optionalArgs ...any) any {
	//
	// fetchTrades (public)
	//
	//      {
	//          "book": "btc_usdt",
	//          "created_at": "2021-11-24T12:14:53+0000",
	//          "amount": "0.00026562",
	//          "maker_side": "sell",
	//          "price": "56471.55",
	//          "tid": "52557338"
	//      }
	//
	// fetchMyTrades (private)
	//
	//      {
	//          "book": "btc_usdt",
	//          "created_at": "2021-11-24T12:31:03+0000",
	//          "minor": "11.30356000",
	//          "major": "-0.00020000",
	//          "fees_amount": "0.01119052",
	//          "fees_currency": "usdt",
	//          "minor_currency": "usdt",
	//          "major_currency": "btc",
	//          "oid": "djTzMIWx2Vi3iMjl",
	//          "tid": "52559051",
	//          "price": "56517.80",
	//          "side": "sell",
	//          "maker_side": "buy"
	//      }
	//
	// fetchOrderTrades (private)
	//
	//      {
	//          "book": "btc_usdt",
	//          "created_at": "2021-11-24T12:30:52+0000",
	//          "minor": "-11.33047916",
	//          "major": "0.00020020",
	//          "fees_amount": "0.00000020",
	//          "fees_currency": "btc",
	//          "minor_currency": "usdt",
	//          "major_currency": "btc",
	//          "oid": "O0D2zcljjjQF5xlG",
	//          "tid": "52559030",
	//          "price": "56595.80",
	//          "side": "buy",
	//          "maker_side": "sell"
	//      }
	//
	market := GetArg(optionalArgs, 0, nil)
	_ = market
	var timestamp any = this.Parse8601(this.SafeString(trade, "created_at"))
	var marketId any = this.SafeString(trade, "book")
	var symbol any = this.SafeSymbol(marketId, market, "_")
	var side any = this.SafeString(trade, "side")
	var makerSide any = this.SafeString(trade, "maker_side")
	var takerOrMaker any = nil
	if IsTrue(!IsEqual(side, nil)) {
		if IsTrue(IsEqual(side, makerSide)) {
			takerOrMaker = "maker"
		} else {
			takerOrMaker = "taker"
		}
	} else {
		if IsTrue(IsEqual(makerSide, "buy")) {
			side = "sell"
		} else {
			side = "buy"
		}
	}
	var amount any = this.SafeString2(trade, "amount", "major")
	if IsTrue(!IsEqual(amount, nil)) {
		amount = Precise.StringAbs(amount)
	}
	var fee any = nil
	var feeCost any = this.SafeString(trade, "fees_amount")
	if IsTrue(!IsEqual(feeCost, nil)) {
		var feeCurrencyId any = this.SafeString(trade, "fees_currency")
		var feeCurrency any = this.SafeCurrencyCode(feeCurrencyId)
		fee = map[string]any{
			"cost":     feeCost,
			"currency": feeCurrency,
		}
	}
	var cost any = this.SafeString(trade, "minor")
	if IsTrue(!IsEqual(cost, nil)) {
		cost = Precise.StringAbs(cost)
	}
	var price any = this.SafeString(trade, "price")
	var orderId any = this.SafeString(trade, "oid")
	var id any = this.SafeString(trade, "tid")
	return this.SafeTrade(map[string]any{
		"id":           id,
		"info":         trade,
		"timestamp":    timestamp,
		"datetime":     this.Iso8601(timestamp),
		"symbol":       symbol,
		"order":        orderId,
		"type":         nil,
		"side":         side,
		"takerOrMaker": takerOrMaker,
		"price":        price,
		"amount":       amount,
		"cost":         cost,
		"fee":          fee,
	}, market)
}

